from pathlib import Path
import re
root=Path(__file__).parent
source=(root/'question-bank-polished.html').read_text(encoding='utf-8-sig')
css=re.search(r'<style>(.*?)</style>',source,re.S).group(1)
brand=re.search(r'<div class="app-brand">.*?</div>',source,re.S).group(0)
nav=re.search(r'<nav>.*?</nav>',source,re.S).group(0)
question_cards=re.findall(r'<article class="card">.*?</article>',source,re.S)[:3]
css+='''
.gallery{grid-template-columns:repeat(2,minmax(0,1fr));max-width:840px;margin:auto;gap:24px}.phone{height:880px}.app-brand{margin-bottom:23px}.btn{font-size:12px;font-weight:600;padding:13px 15px;border:1px solid #51435f;border-radius:12px;background:#2c2635;color:#d7c4f6}.btn.primary{background:#9472f4;color:#fff;border-color:#aa8bfc}.action-row{display:flex;gap:9px;margin-top:22px}.action-row .primary{flex:1}.action-row .more{padding:10px 12px;font-size:19px}.search{margin-top:17px}.filter-row{display:flex;justify-content:space-between;align-items:center;margin:14px 0 18px;font-size:11px;color:#afa1ba}.filter-row .btn{font-size:11px;padding:9px 12px;border-radius:10px}.filter-row small{font-size:10px}.chips{display:flex;gap:7px;margin:12px 0 17px}.chips span{font-size:10px;background:#392b4b;border:1px solid #6a4a8c;color:#d1b7f1;border-radius:20px;padding:7px 10px}.split-search{display:flex;gap:9px;align-items:center;margin:18px 0 14px}.split-search .search{flex:1;margin:0;padding:12px}.split-search .btn{height:46px;width:48px;padding:0;font-size:19px}.wide-create{width:100%;margin:15px 0 9px;display:flex;align-items:center;justify-content:space-between}.utility-row{display:flex;gap:8px;margin-bottom:17px}.utility-row .btn{flex:1;padding:11px 8px;font-size:11px}.heading .head-import{padding:9px 13px;font-size:11px}.floating-create{position:absolute;right:20px;bottom:96px;padding:13px 20px;border:0;border-radius:26px;background:#9976fc;color:white;font-size:13px;font-weight:600;box-shadow:0 8px 30px #09050e99}.filter-panel{background:#28232f;border:1px solid #51415f;border-radius:16px;padding:15px;margin:13px 0 18px}.panel-title{display:flex;justify-content:space-between;font-size:13px;font-weight:600;margin-bottom:17px}.panel-title span:last-child{color:#aa8acf;font-weight:400;font-size:11px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:13px 10px}.field label{display:block;color:#a99bb4;font-size:10px;margin-bottom:7px}.value{background:#201e28;border:1px solid #4c3c58;border-radius:8px;padding:10px;font-size:11px;display:flex;justify-content:space-between;color:#e0d4ed}.checks{display:flex;gap:13px;font-size:10px;color:#b8a8c6;margin:17px 0}.checks b{color:#be95fb}.panel-actions{display:flex;gap:10px;align-items:center}.panel-actions .btn.primary{flex:1;font-size:11px;padding:11px}.panel-actions .reset{border:0;background:none;color:#b59cc9;font-size:11px;padding:8px}.scrim{position:absolute;inset:0;background:#08070fb3;z-index:3}.sheet{position:absolute;bottom:0;left:0;right:0;z-index:4;background:#24212c;border:1px solid #544563;border-bottom:0;border-radius:24px 24px 0 0;padding:12px 21px 24px}.handle{width:40px;height:4px;border-radius:9px;background:#756780;margin:0 auto 21px}.sheet h2{font-size:21px;margin:0 0 7px}.sheet>p{font-size:11px;color:#a899b5;margin:0 0 21px}.sheet .fields{gap:17px 12px}.sheet .value{padding:13px 10px;font-size:12px}.sheet .chips{margin:17px 0}.sheet .panel-actions{border-top:1px solid #4b3c55;padding-top:17px;margin-top:20px}.sheet .panel-actions .btn{padding:14px;font-size:12px}.sheet .checks{font-size:11px;margin:21px 0}.result-line{font-size:10px;color:#a99bb4;margin:15px 0}.control-note{color:#a99fb7;font-size:11px;text-align:center;margin-top:16px}@media(max-width:760px){.gallery{grid-template-columns:1fr;max-width:390px}}
'''
heading='<div class="heading"><div><h1>Questions</h1><p>Your library · 17 questions</p></div></div>'
search='<div class="search"><span>⌕</span><span>Search your questions</span></div>'
action='<div class="action-row"><button class="btn primary">＋ Create question</button><button class="btn">⇧ Import</button><button class="btn more">⋯</button></div>'
fields=''.join(f'<div class="field"><label>{name}</label><div class="value">{value}<span>⌄</span></div></div>' for name,value in [('Question type','Any type'),('Subject','All subjects'),('Topic','All topics'),('Sort by','Newest first')])
sheet='<div class="scrim"></div><div class="sheet"><div class="handle"></div><div class="panel-title"><h2>Advanced filters</h2><span>✕</span></div><p>Find exactly the questions you want.</p><div class="fields">'+fields+'</div><div class="field" style="margin-top:17px"><label>Tags</label><div class="value">Search or choose tags <span>⌕</span></div></div><div class="checks"><span>□ With images</span><span>□ Due</span><span>□ Weak / mistakes</span></div><div class="panel-actions"><button class="reset">Reset all</button><button class="btn primary">Show 17 questions</button></div></div>'
variants=[
('A · Clear action bar',heading+action+search+'<div class="filter-row"><small>17 questions · Newest first ▾</small><button class="btn">☷ Advanced filters</button></div>'+''.join(question_cards)+'<div class="control-note">Export &amp; bulk selection in ⋯</div>'),
('B · Search with filter sheet',heading+action+'<div class="split-search">'+search+'<button class="btn">☷</button></div><div class="toolbar"><span>All questions · Newest first</span><b>Filter</b></div>'+''.join(question_cards)+sheet),
('C · Create dock',heading.replace('</div></div>','</div><button class="btn head-import">⇧ Import</button></div>')+search+'<div class="filter-row"><small>Newest first ▾</small><button class="btn">☷ Filters <b style="color:#c6a3ff">2</b></button></div><div class="chips"><span>With images ×</span><span>Multiple choice ×</span></div><div class="result-line">5 matching questions</div>'+''.join(question_cards[:2])+'<button class="floating-create">＋ Create question</button>'),
('D · Expand filters in place',heading+'<button class="btn primary wide-create"><span>＋ Create question</span><span>→</span></button><div class="utility-row"><button class="btn">⇧ Import questions</button><button class="btn">⇩ Export</button><button class="btn">⋯ More</button></div>'+search+'<div class="filter-panel"><div class="panel-title"><span>☷ Advanced filters</span><span>Collapse ⌃</span></div><div class="fields">'+fields+'</div><div class="checks"><span>□ Images</span><span>□ Due</span><span>□ Weak / mistakes</span></div><div class="panel-actions"><button class="reset">Reset</button><button class="btn primary">Apply filters</button></div></div><div class="result-line">17 questions</div>'+question_cards[0])
]
for n in range(2):
    panels=''.join(f'<section class="concept"><h2>{label}</h2><div class="phone line">{brand}{content}{nav}</div></section>' for label,content in variants[n*2:n*2+2])
    (root/f'question-controls-{n+1}.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RecallFlow · question controls</title><style>{css}</style></head><body><main><h1>Create, Import &amp; Advanced filters</h1><p>Your chosen A question cards · four control layouts · local visual previews only.</p><div class="gallery">{panels}</div><a href="question-controls-{2 if n==0 else 1}.html" style="display:block;margin-top:18px;color:#b89af2;font-size:12px">View the other two options →</a></main></body></html>',encoding='utf-8')
